def vincular_movimientos_con_ventas(apps, schema_editor):
    MovimientoStock = apps.get_model("catalogo", "MovimientoStock")
    Venta = apps.get_model("ventas", "Venta")
    DetalleVenta = apps.get_model("ventas", "DetalleVenta")
    alias = schema_editor.connection.alias
    candidatos = {}

    for movimiento in MovimientoStock.objects.using(alias).filter(
        venta__isnull=True,
        tipo="SALIDA",
        motivo__startswith="Venta #",
    ):
        identificador = movimiento.motivo.removeprefix("Venta #")
        if not identificador.isdigit():
            continue
        clave = (
            int(identificador),
            movimiento.producto_id,
            movimiento.cantidad,
            movimiento.usuario_id,
        )
        candidatos.setdefault(clave, []).append(movimiento)

    for clave, movimientos in candidatos.items():
        if len(movimientos) != 1:
            continue
        venta_id, producto_id, cantidad, usuario_id = clave
        venta = Venta.objects.using(alias).filter(pk=venta_id).first()
        if not venta or venta.cajero_id != usuario_id:
            continue
        if DetalleVenta.objects.using(alias).filter(
            venta_id=venta_id,
            producto_id=producto_id,
            cantidad=cantidad,
        ).count() != 1:
            continue
        movimiento = movimientos[0]
        movimiento.venta_id = venta_id
        movimiento.save(using=alias, update_fields=["venta"])


